head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf00201";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf00201.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_23", attr: "__html", fn: function () { return ([String(String(dma_vo.get("regContnContn")).split("\\\\n").join("<br/>"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(String(dma_vo.get("regContnContn")).split("\\\\n").join("<br/>"))) : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "btn_searchFaqSpec", fn: function () { return String(dma_preVo.get("contnTitle")); } },
        { childId: "btn_searchFaqSpec_2", fn: function () { return String(dma_nextVo.get("contnTitle")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_searchFaqList_onclick
 * @description btn_searchFaqList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchFaqList_onclick = async function(e){
    try {
        await scwin.searchFaqList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00201.btn_searchFaqList_onclick' }); }
};

/**
 * @method
 * @name btn_searchFaqSpec_onclick
 * @description btn_searchFaqSpec 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchFaqSpec_onclick = async function(e){
    try {
        await scwin.searchFaqSpec('' + dma_preVo.get("contnId") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00201.btn_searchFaqSpec_onclick' }); }
};

/**
 * @method
 * @name btn_searchFaqSpec_2_onclick
 * @description btn_searchFaqSpec_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchFaqSpec_2_onclick = async function(e){
    try {
        await scwin.searchFaqSpec('' + dma_nextVo.get("contnId") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00201.btn_searchFaqSpec_2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchFaqList
 * @description search Faq List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchFaqList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchFaqList",
        method: "post",
        action: action ?? "/main/notice.do?method=searchFaqList",
        ref: "dma_searchFaqListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchFaqSpec
 * @description search Faq Spec 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchFaqSpec = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchFaqSpec",
        method: "post",
        action: action ?? "/main/notice.do?method=searchFaqSpec",
        ref: "dma_searchFaqSpecReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchFaqList
 * @description search Faq List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchFaqList = async function () {
    await scwin.tx_fn_searchFaqList('/main/notice.do?method=searchFaqList');
    return;
};

/**
 * @method
 * @name searchFaqSpec
 * @description search Faq Spec 처리
 * @param {String} contnId contnId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchFaqSpec = async function (contnId) {
    $c.util.getComponent('dma_searchFaqListReq').set('contnId', contnId);
    await scwin.tx_fn_searchFaqSpec('/main/notice.do?method=searchFaqSpec');
    return;
};
